<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Enquiries · Lex Factum Admin</title><link rel="stylesheet" href="<?= base_url('styles.css') ?>"><style>
body{background:#080a0c;color:#eee;font-family:Arial,sans-serif}.wrap{max-width:1250px;margin:auto;padding:28px}.top{display:flex;justify-content:space-between;align-items:center;margin-bottom:28px}.brand{color:#d7b878;letter-spacing:.14em;font-size:12px}.links a{color:#bfc1bf;text-decoration:none;margin-left:18px;font-size:12px}.hero{padding:28px 0}.ey{color:#c8a66e;letter-spacing:.18em;font-size:10px}.hero h1{font:500 46px Georgia,serif;margin:10px 0}.hero p{color:#8f9698}.tabs{display:flex;gap:10px;flex-wrap:wrap;margin:20px 0}.tabs a{padding:10px 14px;border:1px solid rgba(255,255,255,.1);border-radius:10px;color:#aaa;text-decoration:none;font-size:11px}.tabs a.active{color:#e0bd7c;border-color:rgba(224,189,124,.4)}.table{border:1px solid rgba(255,255,255,.08);border-radius:18px;overflow:auto;background:rgba(255,255,255,.025)}table{width:100%;border-collapse:collapse;min-width:850px}th,td{padding:15px;text-align:left;border-bottom:1px solid rgba(255,255,255,.06);font-size:12px}th{color:#777f82;font-size:10px;letter-spacing:.12em}td a{color:#d8b979;text-decoration:none}.badge{padding:5px 8px;border-radius:20px;background:rgba(255,255,255,.07);font-size:10px}.empty{padding:50px;text-align:center;color:#777}.danger{color:#c97b7b!important}
</style></head><body><main class="wrap"><div class="top"><span class="brand">LEX FACTUM · REQUESTS</span><div class="links"><a href="<?= site_url('admin') ?>">Admin</a><a href="<?= site_url('admin/cms') ?>">CMS</a><a href="<?= site_url('admin/crm') ?>">CRM</a></div></div><section class="hero"><div class="ey">CLIENT COMMUNICATION</div><h1><?= $filter==='appointment'?'Appointments':($filter==='contact'?'Contact Requests':'Contact & Appointment Requests') ?></h1><p>Manage incoming website enquiries and appointment requests.</p></section><div class="tabs"><a class="<?= $filter==='all'?'active':'' ?>" href="<?= site_url('admin/enquiries') ?>">ALL</a><a class="<?= $filter==='contact'?'active':'' ?>" href="<?= site_url('admin/enquiries/contact') ?>">CONTACT</a><a class="<?= $filter==='appointment'?'active':'' ?>" href="<?= site_url('admin/enquiries/appointments') ?>">APPOINTMENTS</a></div><?php if(session()->getFlashdata('success')): ?><p><?= esc(session()->getFlashdata('success')) ?></p><?php endif; ?><div class="table"><?php if(!$items): ?><div class="empty">No requests yet.</div><?php else: ?><table><thead><tr><th>TYPE</th><th>NAME</th><th>EMAIL</th><th>PHONE</th><th>PRACTICE</th><th>DATE</th><th>STATUS</th><th></th></tr></thead><tbody><?php foreach($items as $item): ?><tr><td><?= esc(strtoupper($item['type'] ?? 'contact')) ?></td><td><a href="<?= site_url('admin/enquiries/'.$item['id']) ?>"><?= esc($item['full_name']) ?></a></td><td><?= esc($item['email']) ?></td><td><?= esc($item['phone'] ?? '') ?></td><td><?= esc($item['practice_area'] ?? '') ?></td><td><?= esc($item['preferred_date'] ?? '') ?> <?= esc($item['preferred_time'] ?? '') ?></td><td><span class="badge"><?= esc($item['status']) ?></span></td><td><a class="danger" href="<?= site_url('admin/enquiries/'.$item['id'].'/delete') ?>" onclick="return confirm('Delete this request?')">Delete</a></td></tr><?php endforeach; ?></tbody></table><?php endif; ?></div></main></body></html>
